const scan = JSON.parse(items[0].json.stdout);

return scan.devices.map(d => ({
  json: {
    device: d.name,
    type: d.type
  }
}));

const parsed = JSON.parse($json.stdout);

return [{
  device: parsed.device?.name,
  model_name: parsed.model_name ?? "Unknown",
  serial: parsed.serial_number ?? "Unknown",
  capacity_gb: parsed.user_capacity?.bytes
    ? parsed.user_capacity.bytes / 1e9
    : null
}];

const seen = new Set();
const output = [];

for (const item of items) {
  const dev = item.json.device;

  // Keep only base block devices
  if (dev.startsWith('/dev/sd')) {
    if (!seen.has(dev)) {
      seen.add(dev);
      output.push(item);
    }
  }
}

return output;

const parsed = JSON.parse($json.stdout);

let wear = null;
if (parsed.ata_smart_attributes?.table) {
  const wl = parsed.ata_smart_attributes.table.find(
    a => a.id === 177 || a.name?.includes("Wear")
  );
  wear = wl?.value ?? null;
}

return [{
  device: parsed.device?.name,
  smart_passed: parsed.smart_status?.passed ?? false,
  temperature_c: parsed.temperature?.current ?? null,
  spare_percent: parsed.spare_available?.current_percent ?? null,
  endurance_used_percent: parsed.endurance_used?.current_percent ?? null,
  wear_leveling: wear
}];

// Get the output from the Read Battery Report node
const output = $json.stdout || '';

// Check if it's an error message
if (output.includes('not found')) {
  return [{
    json: {
      xml: null,
      error: 'Battery report file not found',
      note: 'Run Generate Battery Report first'
    }
  }];
}

// Return the XML content
return [{
  json: {
    xml: output,
    source: 'battery-report.xml'
  }
}];

// ----------------------------------------------------
// CheckTop – Battery Health (Industry Standard Parsing)
// Input: Clean Battery XML node output
// Output: User-trustable battery health report
// ----------------------------------------------------

// 1. Get XML safely
const xml = $json.xml || $json.stdout;
if (!xml || typeof xml !== 'string') {
  throw new Error('Battery XML not found or invalid');
}

// 2. Helper: extract single tag value
function getTag(xmlStr, tag) {
  const match = xmlStr.match(
    new RegExp(`<${tag}>([^<]*)</${tag}>`)
  );
  return match ? match[1].trim() : null;
}

// 3. Extract battery data (Microsoft schema)
const designCapacity = parseInt(getTag(xml, 'DesignCapacity'), 10);
const fullChargeCapacity = parseInt(getTag(xml, 'FullChargeCapacity'), 10);
const cycleCount = parseInt(getTag(xml, 'CycleCount'), 10);

const battery = {
  manufacturer: getTag(xml, 'Manufacturer'),
  chemistry: getTag(xml, 'Chemistry'),
  serial_number: getTag(xml, 'SerialNumber'),
  design_capacity_mWh: designCapacity || null,
  full_charge_capacity_mWh: fullChargeCapacity || null,
  cycle_count: isNaN(cycleCount) ? null : cycleCount
};

// 4. System info (for report clarity)
const system = {
  device_name: getTag(xml, 'ComputerName'),
  brand: getTag(xml, 'SystemManufacturer'),
  model: getTag(xml, 'SystemProductName')
};

// 5. Industry-standard battery health calculation
let batteryHealthPercent = null;
if (designCapacity && fullChargeCapacity) {
  batteryHealthPercent = Math.round(
    (fullChargeCapacity / designCapacity) * 100
  );
}

// 6. Industry-accepted condition labels (simple & trusted)
let condition = 'UNKNOWN';
if (batteryHealthPercent !== null) {
  if (batteryHealthPercent >= 80) condition = 'GOOD';
  else if (batteryHealthPercent >= 60) condition = 'FAIR';
  else condition = 'POOR';
}

// 7. Plain-language message for non-technical users
let userMessage;
if (condition === 'GOOD') {
  userMessage = 'Battery health is good. No immediate action needed.';
} else if (condition === 'FAIR') {
  userMessage = 'Battery health is reduced. Expect shorter battery life.';
} else if (condition === 'POOR') {
  userMessage = 'Battery health is poor. Battery replacement is recommended.';
} else {
  userMessage = 'Battery health could not be determined.';
}

// 8. Final CheckTop-ready output (NO custom scoring)
return [
  {
    json: {
      battery,
      system,
      battery_health_percent: batteryHealthPercent,
      battery_condition: condition,
      user_message: userMessage,
      data_source: 'Windows powercfg battery report'
    }
  }
];

// n8n Function node
// Purpose: Clean and normalize CPU static information

const raw = $json.stdout;

if (!raw) {
  throw new Error('CPU info stdout is missing');
}

const data = JSON.parse(raw);

return [
  {
    json: {
      cpu_info: {
        model: data.Name || null,
        cores: data.NumberOfCores || null,
        threads: data.NumberOfLogicalProcessors || null,
        max_clock_mhz: data.MaxClockSpeed || null
      }
    }
  }
];

// n8n Function node
// Purpose: Convert raw CPU temperature to Celsius
const raw = $json.stdout;
if (!raw) {
  throw new Error('CPU temperature stdout is missing');
}
const data = JSON.parse(raw);
// Windows reports temperature in tenths of Kelvin
// Formula: (Kelvin / 10) - 273.15
const tempCelsius = Math.round((data.CurrentTemperature / 10) - 273.15);
return [
  {
    json: {
      cpu_stress: {
        temperature_celsius: tempCelsius,
        stress_test: "Passed"
      }
    }
  }
];

// Parse stdout safely
const stdout = items[0].json.stdout;
if (!stdout) {
  throw new Error("GPU stdout is empty");
}

const gpu = JSON.parse(stdout);

// AdapterRAM is in bytes
const memoryMb = gpu.AdapterRAM
  ? Math.round(gpu.AdapterRAM / 1024 / 1024)
  : null;

return [
  {
    json: {
      gpu: {
        name: gpu.Name || "Unknown GPU",
        driver_version: gpu.DriverVersion || "Unknown",
        color_depth_bits: gpu.CurrentBitsPerPixel || null,
        memory_mb: memoryMb
      }
    }
  }
];

const gpu = items[0].json.gpu;

let status = "GOOD";
let notes = [];

if (!gpu.name || gpu.name === "Unknown GPU") {
  status = "FAIR";
  notes.push("Graphics adapter information could not be fully identified.");
}

if (!gpu.driver_version || gpu.driver_version === "Unknown") {
  status = "FAIR";
  notes.push("Graphics driver information is missing or outdated.");
}

if (!gpu.memory_mb || gpu.memory_mb < 512) {
  status = "FAIR";
  notes.push("Available graphics memory is limited.");
}

if (notes.length === 0) {
  notes.push("Graphics hardware and driver are functioning normally.");
}

return [
  {
    json: {
      gpu: {
        ...gpu,
        status,
        summary: notes.join(" ")
      }
    }
  }
];

// 1. Ensure stdout exists
if (!$json.stdout) {
  throw new Error('Display info stdout is missing');
}

// 2. Parse stdout JSON string
const data = JSON.parse($json.stdout);

// 3. Extract resolution
const width = data.CurrentHorizontalResolution;
const height = data.CurrentVerticalResolution;

// 4. Validate values
if (!width || !height) {
  throw new Error('Display resolution values not found');
}

// 5. Industry-standard classification
let resolutionClass = 'Below HD';
let status = 'FAIR';
let summary = 'Display is usable but limited for modern workloads.';

if (width >= 1920 && height >= 1080) {
  resolutionClass = 'Full HD (1080p)';
  status = 'GOOD';
  summary = 'Display resolution meets modern standards for work, browsing, and media.';
} else if (width >= 1280 && height >= 720) {
  resolutionClass = 'HD (720p)';
  status = 'FAIR';
  summary = 'Display resolution is acceptable for basic use but limited for productivity.';
}

// 6. Final output
return [
  {
    display: {
      resolution: `${width} × ${height}`,
      resolution_class: resolutionClass,
      status,
      summary
    }
  }
];

// Parse JSON from previous node stdout
const raw = items[0].json.stdout; // string like '[{"Color":"Red","Pixels":-1},...]'
const data = JSON.parse(raw);

let deadPixelCount = 0;
const firstPixel = data[0].Pixels;

// Compare pixels across colors
for (let i = 1; i < data.length; i++) {
  if (data[i].Pixels === firstPixel) deadPixelCount++;
}

// Build result
return [{
  json: {
    dead_pixels: deadPixelCount,
    status: deadPixelCount === 0 ? 'GOOD' : (deadPixelCount < 5 ? 'FAIR' : 'POOR'),
    summary: deadPixelCount === 0 
      ? 'No dead pixels detected.' 
      : `Detected ${deadPixelCount} dead pixels. Minor visual impact.`
  }
}];

const gpu = items.find(i => i.json.gpu)?.json.gpu;
const display = items.find(i => i.json.display)?.json.display;
const deadPixels = items.find(i => i.json.dead_pixels !== undefined)?.json;

return [{
  json: {
    gpu,
    display,
    dead_pixel_check: deadPixels
  }
}];

// ---- Safe JSON parse helper ----
const parse = (v) => {
  try {
    return typeof v === 'string' ? JSON.parse(v) : v;
  } catch {
    return [];
  }
};

// ---- Extract merged inputs ----
const usbControllers = parse(items[0]?.json?.stdout);
const usbHubs = parse(items[1]?.json?.stdout);
const gpus = parse(items[2]?.json?.stdout);

// ---- Normalize to arrays ----
const usbControllerArr = Array.isArray(usbControllers) ? usbControllers : [usbControllers];
const usbHubArr = Array.isArray(usbHubs) ? usbHubs : [usbHubs];
const gpuArr = Array.isArray(gpus) ? gpus : [gpus];

// ---- USB evaluation (industry-safe proxy) ----
const usbOk =
  usbControllerArr.some(c => c?.Status === 'OK') &&
  usbHubArr.some(h => h?.Status === 'OK');

// ---- HDMI evaluation (GPU capability proxy) ----
const hdmiOk =
  gpuArr.some(g => g?.Status === 'OK');

// ---- Final buyer-facing output ----
return [
  {
    json: {
      ports: {
        usb: {
          status: usbOk ? 'GOOD' : 'FAIR',
          summary: usbOk
            ? 'USB controllers and hubs are detected and functioning.'
            : 'USB hardware is detected but physical port testing is recommended.'
        },
        hdmi: {
          status: hdmiOk ? 'GOOD' : 'FAIR',
          summary: hdmiOk
            ? 'System supports external display output.'
            : 'External display output could not be fully verified.'
        }
      }
    }
  }
];

const devices = JSON.parse(items[0].json.stdout);

// Check primary speaker presence
const primarySpeaker = devices.find(d => 
  d.Name.toLowerCase().includes('audio') && 
  d.Manufacturer.toLowerCase() === 'microsoft'
);

const status = primarySpeaker && primarySpeaker.Status === 'OK' ? 'GOOD' : 'FAIR';

return [
  {
    json: {
      speaker: {
        devices_detected: devices.map(d => d.Name),
        status,
        summary:
          status === 'GOOD'
            ? 'Speakers are detected and working normally. Audio output is available.'
            : 'Audio device detected but may require attention or driver update.'
      }
    }
  }
];

const exec = items[0].json;
const gpu = JSON.parse(exec.stdout);

let status = "GOOD";
let summary = "GPU detected and driver information retrieved successfully.";

return [{
  json: {
    status,
    summary,
    raw: {
      name: gpu.Name,
      adapterRAM_MB: Math.round(gpu.AdapterRAM / 1024 / 1024),
      driverVersion: gpu.DriverVersion
    }
  }
}];

const exec = items[0].json;
let modules = JSON.parse(exec.stdout);

// Normalize to array
if (!Array.isArray(modules)) {
  modules = [modules];
}

const totalBytes = modules.reduce((sum, m) => sum + (m.Capacity || 0), 0);
const speeds = [...new Set(modules.map(m => m.Speed))];

let status = "GOOD";
let summary = "RAM configuration appears normal.";

if (speeds.length > 1) {
  status = "WARNING";
  summary = "Mixed RAM speeds detected, which may impact performance.";
}

return [{
  json: {
    status,
    summary,
    raw: {
      totalGB: Math.round(totalBytes / 1024 / 1024 / 1024),
      modules: modules.map(m => ({
        capacityGB: Math.round(m.Capacity / 1024 / 1024 / 1024),
        speedMHz: m.Speed,
        manufacturer: m.Manufacturer,
        partNumber: m.PartNumber.trim()
      }))
    }
  }
}];

const exec = items[0].json;
let drives = JSON.parse(exec.stdout);

// Evaluate each drive
drives = drives.map(d => ({
  name: d.Name,
  usedGB: Math.round(d.Used / 1024 / 1024 / 1024),
  freeGB: Math.round(d.Free / 1024 / 1024 / 1024),
  percentFree: Math.round(d.Free / (d.Free + d.Used) * 100)
}));

// Determine status
let overallStatus = "GOOD";
let summary = "All drives have sufficient free space.";

for (const d of drives) {
  if (d.percentFree < 10) {
    overallStatus = "FAIL";
    summary = `Drive ${d.name} critically low on free space.`;
    break;
  } else if (d.percentFree < 15 && overallStatus !== "FAIL") {
    overallStatus = "WARNING";
    summary = `Drive ${d.name} has low free space.`;
  }
}

return [{
  json: {
    status: overallStatus,
    summary,
    raw: drives
  }
}];

// Parse stdout safely
const exec = items[0].json;
const cpu = JSON.parse(exec.stdout);

let status = "GOOD";
let summary = "CPU clock speeds are within normal operating range.";

if (cpu.LoadPercentage > 50 && cpu.CurrentClockSpeed < cpu.MaxClockSpeed * 0.7) {
  status = "WARNING";
  summary = "CPU frequency appears reduced under load, possible thermal throttling.";
}

return [{
  json: {
    status,
    summary,
    raw: cpu
  }
}];

return [{
  json: {
    category: "storage_smart",
    status: "GOOD",
    summary: "All storage drives passed SMART health checks.",
    details: $input.all().map(i => i.json),
    severity_score: 0,
    buyer_impact: "LOW"
  }
}];

return [{
  json: {
    category: "battery",
    status: $json.battery_condition,
    summary: $json.user_message,
    details: {
      manufacturer: $json.manufacturer,
      design_capacity_mWh: $json.design_capacity_mWh,
      full_charge_capacity_mWh: $json.full_charge_capacity_mWh,
      cycle_count: $json.cycle_count,
      health_percent: $json.battery_health_percent
    },
    severity_score: 0,
    buyer_impact: "LOW"
  }
}];

// Extract battery info from previous node output
const data = items[0].json;

return [{
  json: {
    manufacturer: data.battery.manufacturer,
    chemistry: data.battery.chemistry,
    serial_number: data.battery.serial_number,
    design_capacity_mWh: data.battery.design_capacity_mWh,
    full_charge_capacity_mWh: data.battery.full_charge_capacity_mWh,
    cycle_count: data.battery.cycle_count,
    battery_health_percent: data.battery_health_percent,
    battery_condition: data.battery_condition,
    user_message: data.user_message
  }
}];

const gpu = $json.gpu;
const display = $json.display;
const dead = $json.dead_pixel_check;

let status = "GOOD";
let severity = 0;
let impact = "LOW";

if (dead.status === "FAIR") {
  status = "FAIR";
  severity = 1;
  impact = "MEDIUM";
}

return [{
  json: {
    category: "display_gpu",
    status,
    summary: dead.summary || display.summary,
    details: {
      gpu,
      display,
      dead_pixels: dead.dead_pixels
    },
    severity_score: severity,
    buyer_impact: impact
  }
}];

const cpu = $json.cpu;

return [{
  json: {
    category: "cpu",
    status: cpu.status,
    summary: cpu.summary,
    details: {
      model: cpu.model,
      cores: cpu.cores,
      threads: cpu.threads,
      temperature_celsius: cpu.temperature_celsius,
      stress_test: cpu.stress_test
    },
    severity_score: 0,
    buyer_impact: "LOW"
  }
}];

const cpuInfo = items[0].json.cpu_info;
const stress = items[1].json.cpu_stress;
let status = "GOOD";
let notes = [];
if (stress.temperature_celsius > 75) {
  status = "POOR";
  notes.push("Processor temperature is higher than safe limits.");
}
if (stress.stress_test !== "Passed") {
  status = "POOR";
  notes.push("Processor failed stress stability test.");
}
if (notes.length === 0) {
  notes.push("Processor runs within safe temperature and remained stable under load.");
}
return [
  {
    json: {
      cpu: {
        model: cpuInfo.model,
        cores: cpuInfo.cores,
        threads: cpuInfo.threads,
        temperature_celsius: stress.temperature_celsius,
        stress_test: stress.stress_test,
        status,
        summary: notes.join(" ")
      }
    }
  }
];

return [{
  json: {
    category: "storage_free_space",
    status: $json.status,
    summary: $json.summary,
    details: $json.raw,
    severity_score: 0,
    buyer_impact: "LOW"
  }
}];

return [{
  json: {
    category: "io_audio",
    status: "GOOD",
    summary: "USB ports, HDMI output, and speakers are functioning normally.",
    details: {
      ports: $json.ports,
      speaker: $json.speaker
    },
    severity_score: 0,
    buyer_impact: "LOW"
  }
}];

return [{
  json: {
    category: "cpu_throttling",
    status: $json.status,
    summary: $json.summary,
    details: {
      model: $json.raw.Name,
      max_clock_mhz: $json.raw.MaxClockSpeed,
      current_clock_mhz: $json.raw.CurrentClockSpeed,
      load_percentage: $json.raw.LoadPercentage
    },
    severity_score: 0,
    buyer_impact: "LOW"
  }
}];

return [{
  json: {
    category: "gpu_driver",
    status: $json.status,
    summary: $json.summary,
    details: {
      name: $json.raw.name,
      adapter_ram_mb: $json.raw.adapterRAM_MB,
      driver_version: $json.raw.driverVersion
    },
    severity_score: 0,
    buyer_impact: "LOW"
  }
}];

// Input: Evaluate RAM Modules output
return items.map(item => {
  const raw = item.json.raw || {};
  return {
    json: {
      ram: {
        total_capacity_gb: raw.totalGB || 0,
        average_speed_mhz: raw.modules?.reduce((sum, m) => sum + (m.speedMHz || 0), 0) / (raw.modules?.length || 1),
        status: item.json.status || "UNKNOWN",
        summary: item.json.summary || ""
      }
    }
  };
});

// Branch 2 output (verdict)
const ramHealth = $json.ram;

// Branch 1 output (modules)
const moduleData =
  $items("Evaluate RAM Modules")[0]?.json?.raw || {};

return [{
  json: {
    category: "ram",
    status: ramHealth.status,
    summary: ramHealth.summary,
    details: {
      total_capacity_gb: ramHealth.total_capacity_gb,
      average_speed_mhz: ramHealth.average_speed_mhz,
      modules: (moduleData.modules || []).map(m => ({
        capacity_gb: m.capacityGB,
        speed_mhz: m.speedMHz,
        manufacturer: m.manufacturer,
        part_number: m.partNumber
      }))
    },
    severity_score: 0,
    buyer_impact: "LOW"
  }
}];

// Input: items with confidence_score and hardware details
return items.map(item => {
    // Example baseline price (USD) - adjust based on your market data
    let basePrice = 500;

    // Apply multipliers based on health
    let priceMultiplier = 1;

    if(item.json.category === "battery" && item.json.details.health_percent < 95) {
        priceMultiplier -= 0.10;
    }

    if(item.json.category === "display_gpu" && item.json.details.dead_pixels > 0) {
        priceMultiplier -= 0.05 * Math.ceil(item.json.details.dead_pixels / 5);
    }

    if(item.json.category === "storage_smart") {
        // Assuming spare_percent < 90% or smart_passed false
        const badDrives = item.json.details.filter(d => !d.smart_passed || (d.spare_percent && d.spare_percent < 90));
        if(badDrives.length > 0) priceMultiplier -= 0.10;
    }

    // Reduce price slightly for lower confidence
    if(item.json.confidence_score < 90) priceMultiplier -= 0.05;

    // Calculate recommended price
    item.json.recommended_price_usd = Math.round(basePrice * priceMultiplier / 10) * 10;

    return item;
});

return [
  {
    json: {},
    binary: {
      data: {
        data: Buffer.from(JSON.stringify(items[0].json, null, 2)),
        mimeType: 'application/json',
        fileName: 'checktop_report.json'
      }
    }
  }
];

const html = $json.output || $json.html;

return [
  {
    binary: {
      data: {
        data: Buffer.from(html, 'utf8'),
        mimeType: 'text/html',
        fileName: 'checktop_report.html'
      }
    }
  }
];

const merged = {
  meta: {
    tool: "CheckTop",
    version: "1.0",
    generated_at: new Date().toISOString()
  },
  diagnostics: [],
};

for (const item of items) {
  if (Array.isArray(item.json)) {
    merged.diagnostics.push(...item.json);
  } else if (item.json?.category) {
    merged.diagnostics.push(item.json);
  }
}

return [{ json: merged }];

const report = items[0].json;

report.diagnostics = Array.isArray(report.diagnostics)
  ? report.diagnostics
  : [];

return [{ json: report }];

const report = items[0].json;

report.diagnostic_confidence = {
  confidence_level: "HIGH",
  confidence_percent: 95,
  basis: "Direct system-level checks via OS diagnostics"
};

return [{ json: report }];

const report = items[0].json;

let lines = [];

for (const d of report.diagnostics) {
  lines.push(
    `- ${d.category.toUpperCase()}: ${d.status}. ${d.summary || ""}`
  );
}

report.ai_summary = `CheckTop Laptop Health Summary:\n${lines.join("\n")}`;

return [{ json: report }];

const report = items[0].json;

let minor = 0, major = 0, critical = 0;

for (const d of report.diagnostics) {
  if (d.severity_score === 1) minor++;
  if (d.severity_score === 2) major++;
  if (d.severity_score >= 3) critical++;
}

let verdict = "EXCELLENT";
let headline = "Laptop is in excellent condition";
let summary = "All major components are functioning normally.";

if (critical > 0) {
  verdict = "POOR";
  headline = "Laptop has critical issues";
  summary = "Critical hardware faults detected. Purchase not advised.";
} else if (major > 0) {
  verdict = "FAIR";
  headline = "Laptop has notable issues";
  summary = "Some components may affect long-term usability.";
} else if (minor > 0) {
  verdict = "GOOD";
  headline = "Laptop is in good condition";
  summary = "Minor non-critical issues detected.";
}

report.verdict = verdict;
report.buyer_summary = { headline, summary, verdict };

return [{ json: report }];

const report = items[0].json;

for (const d of report.diagnostics) {
  if (typeof d.severity_score !== "number") {
    if (d.status === "GOOD") d.severity_score = 0;
    else if (d.status === "FAIR") d.severity_score = 1;
    else if (d.status === "BAD") d.severity_score = 2;
    else d.severity_score = 0;
  }
}

return [{ json: report }];

const report = items[0].json;

const BASE_PRICE = 500;
let adjustedPrice = BASE_PRICE;

if (!Array.isArray(report.diagnostics)) {
  report.pricing = {
    baseline_price_usd: BASE_PRICE,
    recommended_price_usd: BASE_PRICE,
    reason: "No diagnostics available for depreciation"
  };
  return [{ json: report }];
}

for (const d of report.diagnostics) {

  if (d.severity_score === 1) adjustedPrice *= 0.96;
  else if (d.severity_score === 2) adjustedPrice *= 0.90;
  else if (d.severity_score >= 3) adjustedPrice *= 0.80;

  if (d.category === "display_gpu" && d.details?.dead_pixels > 0) {
    const pixelPenalty = Math.min(d.details.dead_pixels, 10) * 0.01;
    adjustedPrice *= (1 - pixelPenalty);
  }

  if (d.category === "battery" && d.details?.health_percent < 90) {
    adjustedPrice *= 0.95;
  }
}

adjustedPrice = Math.round(adjustedPrice / 10) * 10;

report.pricing = {
  baseline_price_usd: BASE_PRICE,
  recommended_price_usd: adjustedPrice,
  pricing_basis: "Verified diagnostic-based depreciation",
  disclaimer: "Indicative resale price; market conditions may vary"
};

return [{ json: report }];
